(function(E){ const x = E["ai-m2"] = E["ai-m2"] || {units:{}}; x.units["ai-8"] = {"grammar":{"id":"c-ai-8-g","level":"B1","course":"ai-internet","unit":"ai-8","title":"Asking for one change: change only, keep, without","titleTr":"Tek değişiklik istemek: change only, keep, without","titleFa":"فقط یک تغییر بخواه: change only، keep، without","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["Change only + noun","Change only the background."],["Keep + noun","Keep the cup and the table."],["without + noun","The same room, without people."]]},"wrong":"Only change background and keep other all.","right":"Change only the background. Keep everything else.","blank":{"sentence":"___ only the colour of the van.","word":"Change","distractors":["Changing","To change"]},"wrong2":"The same room without any of people.","right2":"The same room, without people.","blank2":{"sentence":"Show the same office, ___ people.","word":"without","distractors":["no with","not with"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Only goes right after change.","tr":"only, change'den hemen sonra gelir.","fa":"only درست بعد از change می‌آید.","ex":"Change only the light."},{"en":"Without takes a noun or -ing.","tr":"without'tan sonra isim ya da -ing gelir.","fa":"بعد از without اسم یا ‎-ing می‌آید.","ex":"without text"}],"test":{"en":"Does your message change just one thing?","tr":"Mesajın yalnızca tek şeyi mi değiştiriyor?","fa":"پیامت فقط یک چیز را تغییر می‌دهد؟"}},"errorWatch":[{"find":["keep other all"],"fix":{"en":"Say \"keep everything else\".","tr":"\"keep everything else\" de.","fa":"بگو «keep everything else»."}}]},"b2":{"id":"c-ai-8-b2","level":"B2","course":"ai-internet","unit":"ai-8","track":"B2","title":"Saying what caused it: because of, so, too","titleTr":"Nedeni söylemek: because of, so, too","titleFa":"گفتن علت: because of، so، too","formsTable":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["too + adjective","The picture is too dark."],["because of + noun","It's dark because of the evening light."]]},"wrong":"It's dark because the evening light.","right":"It's dark because of the evening light.","blank":{"sentence":"It's busy ___ the word \"crowded\".","word":"because of","distractors":["because","so"]},"wrong2":"It's very too dark.","right2":"It's too dark.","blank2":{"sentence":"The picture is ___ dark to use.","word":"too","distractors":["very too","so much"]},"expParts":{"tryFrom":"blank","rule":[{"en":"Too means more than you want.","tr":"too, istediğinden fazla demektir.","fa":"too یعنی بیشتر از چیزی که می‌خواهی.","ex":"It's too busy."},{"en":"Because of takes a noun.","tr":"because of'tan sonra isim gelir.","fa":"بعد از because of اسم می‌آید.","ex":"because of the word evening"}],"test":{"en":"Is a noun next? Use because of.","tr":"Sonra isim mi geliyor? because of kullan.","fa":"بعدش اسم آمده؟ از because of استفاده کن."}},"errorWatch":[{"find":["very too"],"fix":{"en":"Don't use very with too.","tr":"too ile very kullanma.","fa":"very را با too نیاور."}}],"useIn":{"en":"B2: explain one fix: say which word caused the problem.","tr":"B2: Bir düzeltmeyi açıkla: sorunu hangi kelimenin yarattığını söyle.","fa":"B2: یک اصلاح را توضیح بده: بگو کدام کلمه مشکل را ایجاد کرده است."},"exitItem":{"from":"ai-8","kind":"blank","prompt":"The picture is dark ___ the word \"evening\".","options":["because of","because","so"],"correct":0}},"vocab":{"id":"c-ai-8-v","level":"B1","category":"vocab","course":"ai-internet","unit":"ai-8","goals":["career"],"title":{"en":"Fixing pictures","tr":"Görsel düzeltmek","fa":"درست کردن تصویر"},"cards":[{"word":"Vary: Subtle or Strong","sentence":"Use Vary to get new versions.","meaning":{"en":"Makes new versions. Subtle changes small details. Strong changes more but keeps the main theme.","tr":"Yeni sürümler üretir. Subtle küçük ayrıntıları değiştirir. Strong daha çok değiştirir ama ana temayı korur.","fa":"نسخه‌های جدید می‌سازد. گزینه‌ی Subtle جزئیات کوچک را عوض می‌کند و گزینه‌ی Strong بیشتر تغییر می‌دهد، ولی موضوع اصلی را نگه می‌دارد."}},{"word":"Stealth","sentence":"Stealth is only on higher plans.","meaning":{"en":"Keeps new images out of public view as far as it can (its terms say \"best efforts\"). Only on higher plans.","tr":"Yeni görselleri olabildiğince herkese açık alandan uzak tutar (koşullarında \"best efforts\" yazar). Yalnızca üst planlarda.","fa":"تا جایی که بتواند تصویرهای جدید را از دید عموم دور نگه می‌دارد (در شرایط استفاده‌اش نوشته است «best efforts»). فقط در پلن‌های بالاتر."}},{"word":"--ar 16:9","sentence":"Add --ar 16:9 for a wide picture.","meaning":{"en":"Sets the aspect ratio: width compared with height. Write it at the end of the prompt. Square (1:1) is the default.","tr":"En-boy oranını belirler: genişliğin yüksekliğe oranı. Prompt'un sonuna yaz. Varsayılan kare (1:1) biçimdir.","fa":"نسبت تصویر را تعیین می‌کند: عرض در مقایسه با ارتفاع. آن را آخر پرامپت بنویس. حالت پیش‌فرض مربع (1:1) است."}},{"word":"--no people","sentence":"Add --no people at the end.","meaning":{"en":"Tells it what you don't want","tr":"Ne istemediğini söyler","fa":"می‌گوید چه چیزی نمی‌خواهی"}},{"word":"aspect ratio","sentence":"Choose the aspect ratio first.","meaning":{"en":"The width compared with the height.","tr":"Genişliğin yüksekliğe oranı.","fa":"عرض در مقایسه با ارتفاع."}},{"word":"background","sentence":"Change only the background.","meaning":{"en":"The part behind the main subject.","tr":"Ana konunun arkasındaki kısım.","fa":"بخشی که پشت موضوع اصلی است."}}]},"judge":{"id":"c-ai-8-j","course":"ai-internet","unit":"ai-8","type":"judge","title":{"en":"What is the best next change?","tr":"En iyi sonraki değişiklik ne?","fa":"بهترین تغییر بعدی چیست؟"},"prompt":"Read each problem and choose one change.","parts":["--no people","--ar 16:9","Change only the light","Check the letters"],"instruction":{"en":"Choose one fix for each problem. These are our own examples, not Midjourney results.","tr":"Her sorun için bir düzeltme seç. Bunlar bizim örneklerimiz, Midjourney sonuçları değil.","fa":"برای هر مشکل یک اصلاح انتخاب کن. این‌ها نمونه‌های خودمان هستند، نه نتیجه‌های Midjourney."},"mode":"single","screen":{"id":"scr-midjourney-1","src":"courses/ai-internet/assets/scr-midjourney-1.webp?v=312f8e4ab0","alt":"Our drawing of a Midjourney-style Create page, November 2026, not a screenshot. The Imagine bar at the top, a grid of four simple room pictures, and the words Vary, Subtle and Strong from the Creation Actions part of an open image."},"images":[{"id":"img-l8-1","label":"example image","src":"courses/ai-internet/assets/img-l8-1.webp?v=335aa4c2cc","alt":"Example image: an office with four people standing in the middle of the room."},{"id":"img-l8-2","label":"example image","src":"courses/ai-internet/assets/img-l8-2.webp?v=462826df87","alt":"Example image: a square picture of a long meeting room, with the wide room cut off at both sides."}],"items":[{"by":"Example problem","image":"img-l8-1","answer":"Extra people in a room that should be empty.","present":["--no people"],"fix":{"en":"Use --no in Midjourney. In a chat tool, write \"Leave out people.\"","tr":"Midjourney'de --no kullan. Sohbet aracında \"Leave out people.\" yaz.","fa":"در Midjourney از --no استفاده کن. در ابزار چت بنویس «Leave out people.»"}},{"by":"Example problem","image":"img-l8-2","answer":"The picture is square, but you need a wide banner.","present":["--ar 16:9"],"fix":{"en":"--ar sets the shape.","tr":"--ar biçimi belirler.","fa":"تنظیم --ar شکل کادر را تعیین می‌کند."}},{"by":"Example problem","answer":"The room is right, but it is too dark.","present":["Change only the light"],"fix":{"en":"One change, so you can see what helped.","tr":"Tek değişiklik, böylece neyin işe yaradığını görürsün.","fa":"فقط یک چیز را عوض کن تا ببینی چه چیزی کمک کرده است."}},{"by":"Example problem","answer":"The sign says OPPEN.","present":["Check the letters"],"fix":{"en":"Tools often get text wrong. Fix it or remove it.","tr":"Araçlar yazıyı sık sık yanlış yapar. Düzelt ya da çıkar.","fa":"ابزارها اغلب متن را غلط می‌نویسند. درستش کن یا حذفش کن."}}]},"speaking":{"id":"ai-8","course":"ai-internet","unit":"ai-8","topic":{"en":"Say why a picture went wrong","tr":"Görselin neden yanlış çıktığını söyle","fa":"بگو چرا تصویر درست از کار درنیامد"},"warmup":{"en":"What do you check first in a picture from an AI tool?","tr":"Yapay zekâ görselinde ilk neye bakarsın?","fa":"در تصویر ابزار هوش مصنوعی اول چه چیزی را بررسی می‌کنی؟"},"questions":[{"en":"Say what is wrong with a picture, and the one change you will try first.","tr":"Görselde neyin yanlış olduğunu ve önce deneyeceğin tek değişikliği söyle.","fa":"بگو در تصویر چه چیزی نادرست است و اول کدام تغییر را امتحان می‌کنی."},{"en":"You need a wide picture, but it came out square. Say what you change, in Midjourney and in a chat tool.","tr":"Geniş bir görsel lazım ama kare çıktı. Midjourney'de ve sohbet aracında neyi değiştireceğini söyle.","fa":"تصویر عریض لازم داری، ولی مربع درآمده. بگو در Midjourney و در ابزار چت چه چیزی را عوض می‌کنی."},{"en":"A colleague changed five things at once. Say why that is a problem.","tr":"Bir meslektaşın beş şeyi birden değiştirdi. Bunun neden sorun olduğunu söyle.","fa":"همکارت پنج چیز را یکجا عوض کرده. بگو چرا این مشکل است."}],"followups":[{"en":"Now say it again about your own work. Use made-up names and numbers.","tr":"Şimdi aynısını kendi işin için söyle. Uydurma ad ve sayılar kullan.","fa":"حالا همین را درباره‌ی کار خودت بگو. از نام‌ها و عددهای ساختگی استفاده کن."}],"expressions":[{"phrase":"The problem is that...","meaning":{"en":"Names the problem.","tr":"Sorunu söyler.","fa":"مشکل را می‌گوید."}},{"phrase":"I'll change only...","meaning":{"en":"Gives one change.","tr":"Tek bir değişiklik söyler.","fa":"یک تغییر را می‌گوید."}}],"model":"I'd like a picture of an empty room. The problem is that this one has people in it. I think the words no people didn't work. I'll change only that part first, and I'll keep everything else the same. Then I'll look again. It should look wide, so I'll fix the shape next.","selfCheck":[{"en":"I did every point of the task.","tr":"Görevin her noktasını yaptım.","fa":"همه‌ی نکته‌های تمرین را انجام دادم."},{"en":"I used at least two phrases from this lesson.","tr":"Bu dersten en az iki ifade kullandım.","fa":"دست‌کم دو عبارت از این درس به کار بردم."},{"en":"I spoke in short, clear sentences.","tr":"Kısa ve net cümlelerle konuştum.","fa":"با جمله‌های کوتاه و روشن حرف زدم."},{"en":"I chose one change, not many.","tr":"Birçok değil, tek bir değişiklik seçtim.","fa":"یک تغییر را انتخاب کردم، نه چند تا."}]},"writing":{"id":"c-ai-8-w","title":{"en":"Fix this picture","tr":"Bu görseli düzelt","fa":"این تصویر را درست کن"},"course":"ai-internet","unit":"ai-8","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"prompt":{"en":"Your prompt was \"a shop window, no people, nice\". The result has people and the wrong shape. You need a wide banner. Write the final prompt for Midjourney and one follow-up for a chat tool.","tr":"Prompt'un şuydu: \"a shop window, no people, nice\". Sonuçta insanlar var ve biçim yanlış. Geniş bir afiş lazım. Midjourney için son prompt'u ve sohbet aracı için bir takip mesajı yaz.","fa":"پرامپتت این بود: «a shop window, no people, nice». در تصویر آدم هست و شکل کادر هم نادرست است. بنر عریض لازم داری. پرامپت نهایی برای Midjourney و یک پیام پیگیری برای ابزار چت بنویس."},"model":"Midjourney: a small shop window with handmade soap, soft morning light, wide shot, photorealistic --ar 16:9 --no people\n\nChat tool: Make it wide, 16:9. Leave out people. Keep everything else.","frame":"Midjourney: a ___ shop window with ___, ___ light, ___ --ar 16:9 --no ___\n\nChat tool: Make it wide, 16:9. Leave out ___. Keep everything else.","words":[{"word":"--ar"},{"word":"--no"},{"word":"Keep everything else"}],"minWords":18,"minSentences":2,"rubric":["Task done: every point of the task is there","Organised: clear parts, in a sensible order","Language: the phrases of this lesson, used correctly","Tone: clear and honest; nothing you cannot explain"],"rubricI18n":{"tr":["Görev: görevin her noktası var","Düzen: açık bölümler, mantıklı sıra","Dil: bu dersin ifadeleri, doğru kullanılmış","Üslup: açık ve dürüst; açıklayamayacağın bir şey yok"],"fa":["کامل بودن کار: همه‌ی نکته‌های تمرین آمده","نظم: بخش‌های روشن، با ترتیب منطقی","زبان: عبارت‌های این درس، درست به کار رفته","لحن: روشن و صادق؛ چیزی که نتوانی توضیح بدهی در آن نیست"]},"b2Task":{"en":"B2 track: no frame. Add one sentence saying what caused the problem.","tr":"B2 yolu: hazır çerçeve yok. Sorunun nedenini söyleyen bir cümle ekle.","fa":"مسیر B2: چارچوب آماده نداری. جمله‌ای اضافه کن که بگوید علت مشکل چه بود."},"own":{"en":"Fix your image prompt from Lesson 2.2 in the same way.","tr":"Ders 2.2'deki görsel prompt'unu aynı şekilde düzelt.","fa":"پرامپت تصویر درس ۲.۲ را به همین شکل درست کن."},"routes":[{"t":{"en":"I use an AI tool","tr":"Bir yapay zekâ aracı kullanıyorum","fa":"از یک ابزار هوش مصنوعی استفاده می‌کنم"},"s":{"en":"Try two versions in any image tool you use, changing one thing. Say what changed in the picture.","tr":"Kullandığın herhangi bir görsel aracında, tek şeyi değiştirip iki sürüm dene. Görselde neyin değiştiğini söyle.","fa":"در هر ابزار تصویری که استفاده می‌کنی دو نسخه را با تغییر یک چیز امتحان کن و بگو در تصویر چه عوض شد."}},{"t":{"en":"I don't have a tool","tr":"Bir aracım yok","fa":"ابزاری ندارم"},"s":{"en":"This course does not need a Midjourney plan. Use the example problems in this lesson and write the prompt.","tr":"Bu kurs için Midjourney planı gerekmez. Bu dersteki örnek sorunları kullan ve prompt'u yaz.","fa":"برای این دوره پلن Midjourney لازم نیست. از مشکل‌های نمونه‌ی همین درس استفاده کن و پرامپت را بنویس."},"noTool":true}]},"exit":{"id":"c-ai-8-x","course":"ai-internet","unit":"ai-8","type":"exit","items":[{"from":"ai-8","kind":"mcq","prompt":"What does Midjourney need before you can create?","options":["A paid plan","A Word file","A Gmail account"],"correct":0,"why":{"en":"You must subscribe to a plan first.","tr":"Önce bir plana abone olmalısın.","fa":"اول باید اشتراک بگیری."},"point":2},{"from":"ai-8","kind":"mcq","prompt":"Which tells Midjourney to leave out people?","options":["--no people","\"please no people\"","--ar people"],"correct":0,"why":{"en":"--no is for what you don't want.","tr":"--no istemediğin şey içindir.","fa":"تنظیم --no برای چیزی است که نمی‌خواهی."},"point":4},{"from":"ai-8","kind":"blank","prompt":"___ only the background. Keep everything else.","options":["Changing","Changes","Change"],"correct":2,"why":{"en":"A request starts with the base verb.","tr":"İstek yalın fiille başlar.","fa":"درخواست با شکل ساده‌ی فعل شروع می‌شود."},"point":6},{"from":"ai-7","kind":"blank","prompt":"a ___ bag on a chair","options":["large of black","large black","black large"],"correct":1,"why":{"en":"Size, then colour.","tr":"Önce boyut, sonra renk.","fa":"اول اندازه، بعد رنگ."}},{"from":"ai-5","kind":"mcq","prompt":"What does \"not in the document\" tell you?","options":["The tool can't open this kind of file at all.","The tool found no support for it in your text.","The document has been deleted from the chat."],"correct":1,"why":{"en":"Check it, and don't send it as a fact.","tr":"Kontrol et, gerçek gibi gönderme.","fa":"بررسی‌اش کن و آن را به‌عنوان واقعیت نفرست."}},{"from":"ai-1","kind":"mcq","prompt":"Which is a text assistant?","options":["A camera","Midjourney","Gemini"],"correct":2,"why":{"en":"Gemini answers in a chat.","tr":"Gemini sohbette yanıt verir.","fa":"Gemini در چت جواب می‌دهد."}}]},"explain":{"id":"c-ai-8-e","course":"ai-internet","unit":"ai-8","type":"explain","level":"B1","title":{"en":"Midjourney: fix the picture","tr":"Midjourney: görseli düzelt","fa":"⁨Midjourney⁩: تصویر را درست کن"},"objective":{"en":"After this lesson, you can fix a picture by changing one thing at a time, and say what you changed.","tr":"Bu dersin sonunda görseli her seferinde tek şeyi değiştirerek düzeltebilecek ve neyi değiştirdiğini söyleyebileceksin.","fa":"بعد از این درس می‌توانی تصویر را با عوض کردن یک چیز در هر نوبت درست کنی و بگویی چه چیزی را عوض کردی."},"hook":{"en":"If you change everything at once, you won't know what helped. Change one thing, then look again.","tr":"Her şeyi birden değiştirirsen neyin işe yaradığını bilemezsin. Tek şeyi değiştir, sonra yeniden bak.","fa":"اگر همه‌چیز را یکجا عوض کنی، نمی‌فهمی چه چیزی کمک کرده. یک چیز را عوض کن و دوباره نگاه کن."},"stats":[{"label":{"en":"Minutes","tr":"Dakika","fa":"دقیقه"},"value":"25"},{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"6"},{"label":{"en":"Tasks","tr":"Görev","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What Midjourney is","tr":"Midjourney nedir","fa":"⁨Midjourney⁩ چیست"},"body":{"en":"Midjourney is an AI tool made only for images and video, from the company Midjourney.","tr":"Midjourney, yalnızca görsel ve video için yapılmış bir yapay zekâ aracıdır; aynı adlı şirketin ürünüdür.","fa":"⁨Midjourney⁩ یک ابزار هوش مصنوعی است که فقط برای تصویر و ویدیو ساخته شده و نام شرکت سازنده‌اش هم همین است."},"steps":[{"en":"It isn't a chat assistant. You describe a picture, and it makes several versions.","tr":"Sohbet asistanı değildir. Bir görseli anlatırsın, o da birkaç sürüm üretir.","fa":"دستیار چت نیست. تصویری را توصیف می‌کنی و چند نسخه از آن می‌سازد.","ex":"a small red van, wide shot"},{"en":"Some settings go inside the prompt, after two dashes.","tr":"Bazı ayarlar prompt'un içine, iki çizgiden sonra yazılır.","fa":"بعضی تنظیم‌ها داخل پرامپت و بعد از دو خط تیره می‌آیند.","ex":"--ar 16:9 --no people"}],"tip":{"en":"As of October 2026. Tools change.","tr":"Ekim 2026 itibarıyla. Araçlar değişebilir.","fa":"به‌روز تا اکتبر ۲۰۲۶. ابزارها تغییر می‌کنند."}},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"What it is good for, and not","tr":"Neye yarar, neye yaramaz","fa":"به چه کاری می‌آید و به چه کاری نه"},"steps":[{"en":"Pictures with a strong look: illustration, mood, a visual idea","tr":"Güçlü bir görünümü olan görseller: illüstrasyon, atmosfer, görsel bir fikir","fa":"تصویرهایی با ظاهر قوی: تصویرسازی، حال‌وهوا، یک ایده‌ی تصویری","ex":"a watercolour poster idea for a cafe"},{"en":"Trying many versions of one idea","tr":"Bir fikrin birçok sürümünü denemek","fa":"امتحان کردن نسخه‌های زیاد از یک ایده","ex":"Vary: Subtle or Strong"},{"en":"Not the best: text answers, emails or research. It is not a chat assistant for those.","tr":"En iyisi değil: Metin yanıtları, e-postalar ya da araştırma. Bunlar için bir sohbet asistanı değildir.","fa":"بهترین گزینه نیست: جواب متنی، ایمیل یا تحقیق. برای این کارها دستیار چت نیست.","ex":"Emails? Use a text assistant."},{"en":"Not the best: secret designs. Images are public by default, and hiding them needs a higher plan.","tr":"En iyisi değil: Gizli tasarımlar. Görseller varsayılan olarak herkese açıktır; gizlemek için üst plan gerekir.","fa":"بهترین گزینه نیست: طرح‌های محرمانه. تصویرها به‌طور پیش‌فرض عمومی‌اند و برای پنهان کردنشان پلن بالاتری لازم است.","ex":"Secret product? Don't describe it."},{"en":"Not the best: learners with no budget. You need a paid plan to create. Try the same picture words in a chat tool.","tr":"En iyisi değil: Bütçesi olmayanlar. Görsel üretmek için ücretli plan gerekir. Aynı görsel kelimelerini bir sohbet aracında dene.","fa":"بهترین گزینه نیست: وقتی بودجه نداری، چون برای ساختن تصویر پلن پولی لازم است. همین کلمه‌های تصویری را در یک ابزار چت امتحان کن.","ex":"No plan? Same words in a chat tool."}]},{"eyebrow":{"en":"The tool","tr":"Araç","fa":"ابزار"},"head":{"en":"How to start","tr":"Nasıl başlanır","fa":"چطور شروع کنی"},"steps":[{"en":"Go to midjourney.com and log in.","tr":"midjourney.com adresine git ve giriş yap.","fa":"به ⁨midjourney.com⁩ برو و وارد شو."},{"en":"To create there, you need a paid plan; the site has no free trial. This course does not ask you to pay: you can do every task without an account.","tr":"Orada görsel üretmek için ücretli plan gerekir; sitede ücretsiz deneme yok. Bu kurs senden ödeme istemez: tüm görevler hesap olmadan da yapılabilir.","fa":"برای ساختن تصویر در این سایت پلن پولی لازم است و سایت نسخه‌ی آزمایشی رایگان ندارد. این دوره از تو پولی نمی‌خواهد: همه‌ی تمرین‌ها را بدون حساب هم می‌توانی انجام بدهی."},{"en":"Open Create. Type your prompt in the Imagine bar at the top and press Enter.","tr":"Create'i aç. Üstteki Imagine çubuğuna prompt'unu yaz ve Enter'a bas.","fa":"⁨Create⁩ را باز کن. پرامپتت را در نوار ⁨Imagine⁩ در بالا بنویس و ⁨Enter⁩ را بزن."},{"en":"Click an image. Vary and Upscale are in the Creation Actions part.","tr":"Bir görsele tıkla. Vary ve Upscale, Creation Actions bölümündedir.","fa":"روی یک تصویر کلیک کن. گزینه‌های ⁨Vary⁩ و ⁨Upscale⁩ در بخش ⁨Creation Actions⁩ هستند."}],"phrases":[{"phrase":"a small white ceramic coffee cup on a wooden table, morning light from a window, close-up, photorealistic --ar 16:9","meaning":{"en":"A detailed description, not an instruction. The shape goes at the end. Results vary.","tr":"Talimat değil, ayrıntılı bir betimleme. Biçim sonda yer alır. Sonuçlar değişir.","fa":"این یک توصیف دقیق است، نه دستور. شکل کادر هم آخر پرامپت می‌آید. نتیجه هر بار فرق می‌کند."},"copy":true}],"tip":{"en":"No account, or it doesn't open? That's fine: the practice in this lesson uses fixed examples. More words and prompts are in this tool's guide.","tr":"Hesabın yok ya da açılmıyor mu? Sorun değil: Bu dersin uygulamasında sabit örnekler var. Diğer kelimeler ve prompt'lar bu aracın rehberinde.","fa":"حساب نداری یا باز نمی‌شود؟ اشکالی ندارد: تمرین‌های این درس نمونه‌های آماده دارند. کلمه‌ها و پرامپت‌های بیشتر در راهنمای این ابزار هستند."}},{"head":{"en":"Two settings in the prompt","tr":"Prompt'ta iki ayar","fa":"دو تنظیم داخل پرامپت"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"Midjourney reads settings after two dashes. A chat tool doesn't, so there you say the same thing in plain words.","tr":"Midjourney ayarları iki çizgiden sonra okur. Sohbet aracı okumaz; orada aynısını düz cümleyle söylersin.","fa":"⁨Midjourney⁩ تنظیم‌ها را بعد از دو خط تیره می‌خواند. ابزار چت نه؛ آنجا همین را با جمله‌ی ساده می‌گویی."},"steps":[{"en":"In Midjourney, unwanted things go after --no, because writing \"no people\" in the description may still bring people.","tr":"Midjourney'de istenmeyen şeyler --no'dan sonra yazılır, çünkü betimlemede \"no people\" yazmak yine de insan getirebilir.","fa":"در ⁨Midjourney⁩ چیزهای ناخواسته را بعد از ⁨--no⁩ بنویس، چون نوشتن «⁨no people⁩» در توصیف باز هم ممکن است آدم بیاورد.","ex":"a quiet office --no people"},{"en":"In a chat tool, say it plainly.","tr":"Sohbet aracında düz cümleyle söyle.","fa":"در ابزار چت همین را ساده بگو.","ex":"Leave out people."},{"en":"In Midjourney, aspect ratio is width compared with height. 16:9 is wide and 1:1 is square.","tr":"Midjourney'de aspect ratio, genişliğin yüksekliğe oranıdır. 16:9 geniş, 1:1 karedir.","fa":"در ⁨Midjourney⁩، عبارت ⁨aspect ratio⁩ یعنی عرض در مقایسه با ارتفاع. 16:9 عریض است و 1:1 مربع.","ex":"a meeting room --ar 16:9"},{"en":"In a chat tool, say the shape.","tr":"Sohbet aracında biçimi söyle.","fa":"در ابزار چت شکل کادر را بگو.","ex":"Make it wide, 16:9."}],"tip":{"en":"Results vary. --no makes people less likely, not impossible. Always look at the result.","tr":"Sonuçlar değişir. --no insan çıkma ihtimalini azaltır ama sıfırlamaz. Sonuca mutlaka bak.","fa":"نتیجه‌ها یکسان نیستند. تنظیم ⁨--no⁩ احتمال آمدن آدم را کم می‌کند، ولی صفر نمی‌کند. پس همیشه نتیجه را نگاه کن."}},{"head":{"en":"Change one thing at a time","tr":"Her seferinde tek şeyi değiştir","fa":"هر بار یک چیز را عوض کن"},"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"body":{"en":"If you change five things and the picture improves, you don't know which one helped. Change one, look, then change the next.","tr":"Beş şeyi değiştirip görsel iyileşirse hangisinin işe yaradığını bilemezsin. Birini değiştir, bak, sonra diğerine geç.","fa":"اگر پنج چیز را عوض کنی و تصویر بهتر شود، نمی‌دانی کدام کمک کرده. یکی را عوض کن، نگاه کن و بعد سراغ بعدی برو."},"phrases":[{"phrase":"Change only the background. Keep everything else.","meaning":{"en":"A follow-up for a chat tool.","tr":"Sohbet aracı için takip mesajı.","fa":"پیام پیگیری برای ابزار چت."},"copy":true}],"tip":{"en":"Any image from this course is labelled \"example image\". None was made with Midjourney. We did not run these example prompts in Midjourney.","tr":"Bu kursun görsellerinde \"example image\" yazar. Hiçbiri Midjourney ile yapılmadı. Bu örnek prompt'ları Midjourney'de çalıştırmadık.","fa":"روی هر تصویر این دوره نوشته شده است «⁨example image⁩». هیچ‌کدام با ⁨Midjourney⁩ ساخته نشده‌اند. این پرامپت‌های نمونه را هم در ⁨Midjourney⁩ اجرا نکرده‌ایم."}},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Asking for one change: change only, keep, without","tr":"Tek değişiklik istemek: change only, keep, without","fa":"فقط یک تغییر بخواه: ⁨change only⁩، ⁨keep⁩، ⁨without⁩"},"steps":[{"en":"Only goes right after change.","tr":"only, change'den hemen sonra gelir.","fa":"⁨only⁩ درست بعد از ⁨change⁩ می‌آید.","ex":"Change only the light."},{"en":"Without takes a noun or -ing.","tr":"without'tan sonra isim ya da -ing gelir.","fa":"بعد از ⁨without⁩ اسم یا ‎⁨-ing⁩ می‌آید.","ex":"without text"}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["Change only + noun","Change only the background."],["Keep + noun","Keep the cup and the table."],["without + noun","The same room, without people."]]},"wrong":"Same picture, no people, don't change other.","right":"Keep everything the same, but remove the people."}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Fix a picture in two steps","tr":"Görseli iki adımda düzelt","fa":"تصویر را در دو قدم درست کن"},"item":"Example problem: a meeting room with six people, square. You need a wide picture.\nPrompt: a quiet meeting room, no people","answer":"a quiet meeting room --ar 16:9 --no people","walk":[{"en":"Name the problems: people, wrong shape.","tr":"Sorunları söyle: insanlar, yanlış biçim.","fa":"مشکل‌ها را بگو: آدم‌ها، شکل نادرست."},{"en":"Move \"no people\" to --no.","tr":"\"no people\" ifadesini --no'ya taşı.","fa":"به‌جای «⁨no people⁩» از ⁨--no⁩ استفاده کن."},{"en":"Add the shape at the end.","tr":"Biçimi sona ekle.","fa":"شکل کادر را آخر پرامپت اضافه کن."}],"why":{"en":"In the first prompt the words \"no people\" may still bring people, and the shape stays square, the default. The second puts both in settings, so you are more likely to get what you asked for.","tr":"İlk prompt'ta \"no people\" kelimeleri yine insan getirebilir, biçim de varsayılan olan kare kalır. İkincisi ikisini de ayarlara yazar, böylece istediğini alma ihtimalin artar.","fa":"در پرامپت اول کلمه‌های «⁨no people⁩» باز هم ممکن است آدم بیاورند و شکل کادر هم همان مربع پیش‌فرض می‌ماند. پرامپت دوم هر دو را در تنظیم‌ها می‌گوید، پس احتمالش بیشتر است همان چیزی را بگیری که خواسته‌ای."}},"quick":{"prompt":"You need a picture for a newsletter, and you have no budget for a Midjourney plan. What do you do?","options":["Use the same picture words in a chat tool.","Wait until you can pay for a plan.","Ask Midjourney for a free text answer."],"correct":0,"why":{"en":"The picture words work in a chat tool too.","tr":"Görsel kelimeleri sohbet aracında da işe yarar.","fa":"کلمه‌های تصویری در ابزار چت هم جواب می‌دهند."}},"quickAfter":3,"remember":{"en":"Find out how each tool wants exclusions, then change one thing at a time. You can now say why a picture went wrong and fix it step by step.","tr":"Her aracın çıkarılacak şeyleri nasıl istediğini öğren, sonra her seferinde tek şeyi değiştir. Artık görselin neden yanlış çıktığını söyleyebilir ve adım adım düzeltebilirsin.","fa":"اول ببین در هر ابزار چطور باید بگویی چه چیزی در تصویر نباشد و بعد هر بار فقط یک چیز را عوض کن. حالا می‌توانی بگویی چرا تصویر درست درنیامده و قدم‌به‌قدم درستش کنی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر ⁨B2⁩"},"head":{"en":"Saying what caused it: because of, so, too","tr":"Nedeni söylemek: because of, so, too","fa":"گفتن علت: ⁨because of⁩، ⁨so⁩، ⁨too⁩"},"steps":[{"en":"Too means more than you want.","tr":"too, istediğinden fazla demektir.","fa":"⁨too⁩ یعنی بیشتر از چیزی که می‌خواهی.","ex":"It's too busy."},{"en":"Because of takes a noun.","tr":"because of'tan sonra isim gelir.","fa":"بعد از ⁨because of⁩ اسم می‌آید.","ex":"because of the word evening"}],"table":{"headers":{"en":["Pattern","Example"],"tr":["Kalıp","Örnek"],"fa":["الگو","مثال"]},"rows":[["too + adjective","The picture is too dark."],["because of + noun","It's dark because of the evening light."]]},"body":{"en":"B2: explain one fix: say which word caused the problem.","tr":"B2: Bir düzeltmeyi açıkla: sorunu hangi kelimenin yarattığını söyle.","fa":"⁨B2⁩: یک اصلاح را توضیح بده: بگو کدام کلمه مشکل را ایجاد کرده است."}},"tool":"midjourney"}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
